int main(){using namespace astrae::lobby;auto created=build_gacha_visual(4,900010006ULL,18,true);assert(created.is_object());assert(created["Type"].as_i64()==4);assert(created["TableId"].as_string()=="900010006");assert(created["AddedCount"].as_string()=="18");assert(created["Count"].as_string()=="18");assert(created["RewardFlag"].as_i64()==64);assert(created["ReplaceInfos"].is_array()&&created["ReplaceInfos"].size()==0);auto updated=build_gacha_visual(1,std::numeric_limits<uint64_t>::max(),-3,false);assert(updated["Type"].as_i64()==1);assert(updated["TableId"].as_string()=="18446744073709551615");assert(updated["AddedCount"].as_string()=="-3");assert(updated["Count"].as_string()=="-3");assert(updated["RewardFlag"].as_i64()==0);GachaRewardEntry rows[2]{};size_t count=1;rows[0]={0xfeed000000000001ULL,1001,7,9};GachaRewardEntry add{0xabcd000000000001ULL,1001,3,4};std::string error;assert(merge_gacha_reward_entry(rows,&count,1,add,&error));assert(count==1&&rows[0].count==10&&rows[0].auxiliary==9&&rows[0].descriptor==0xfeed000000000001ULL);assert(merge_gacha_reward_entry(rows,&count,2,{0x0000000200000004ULL,2002,5,6},&error));assert(count==2&&rows[1].table_id==2002&&rows[1].count==5&&rows[1].auxiliary==6);assert(!merge_gacha_reward_entry(rows,&count,2,{4,2003,1,0},&error)&&!error.empty());rows[0].count=std::numeric_limits<int32_t>::max();assert(!merge_gacha_reward_entry(rows,&count,2,{1,1001,1,0},&error));assert(!merge_gacha_reward_entry(rows,&count,2,{1,1001,0,0},&error));size_t invalid_count=3;assert(!merge_gacha_reward_entry(rows,&invalid_count,2,{1,1001,1,0},&error));return 0;}
